INSERT INTO ranking_stock_items
    (set_id, content_key, format, title, content_fields, ranking_data, narration, source_note, is_active)
VALUES
    ((SELECT id FROM batch_sets WHERE set_code = 'pref-ranking-1'), '001-gyoza-spend', 'top5-map', 'ぎょうざにお金を使う県',
     '{"hook":"宇都宮か、浜松か——答えはどっちでもなかった。","trivia":"浜松市は単体だと4,051円で堂々の全国トップ級。でも静岡市と合わせた県の平均では3位に落ち着きます。宇都宮市を擁する栃木県は2位。3年平均で王座に立ったのは宮崎県でした。","source_display":"総務省 家計調査 2023〜2025年平均（県庁所在市・政令市の世帯数加重平均で県換算）","result_list":"1位 宮崎県 3,478円\\n2位 栃木県 3,192円\\n3位 静岡県 3,091円\\n4位 滋賀県 2,455円\\n5位 埼玉県 2,412円","value_suffix":"円","subtitle":"全国平均は1,984円","bg_motif":"焼き上がった餃子と立ちのぼる湯気、屋台ののれんと提灯をやわらかく配した和のモチーフ"}', '{"entries":[{"rank":1,"pref_code":45,"value":3478},{"rank":2,"pref_code":9,"value":3192},{"rank":3,"pref_code":22,"value":3091},{"rank":4,"pref_code":25,"value":2455},{"rank":5,"pref_code":11,"value":2412}]}', '{"20s":{"intro":"ぎょうざにお金を使う県！","r5_call":"まずは5位！","r5_name":"埼玉県！","r4_call":"つぎは4位！","r4_name":"滋賀県！","r3_call":"3位はどこだ！","r3_name":"静岡県！","r2_call":"惜しくも2位！","r2_name":"栃木県！","r1_call":"さあ、栄えある1位は！","r1_name":"宮崎県ーっ！","outro":"入ってたかー？保存もよろしくな！"},"30s":{"intro":"ぎょうざにお金を使う県、トップ5！","r5_call":"第5位！","r5_name":"埼玉県！","r5_comment":"関東からの刺客だ！","r4_call":"第4位！","r4_name":"滋賀県！","r4_comment":"まさかの近江！","r3_call":"第3位！","r3_name":"静岡県！","r3_comment":"浜松の底力！","r2_call":"第2位！","r2_name":"栃木県！","r2_comment":"宇都宮、あと一歩！","r1_call":"さあ第1位、ぎょうざ王は！","r1_name":"宮崎県ーっ！","recap":"宮崎、栃木、静岡、滋賀、埼玉！","outro":"保存もよろしくな！"}}', '出典: 総務省統計局「家計調査 品目別都道府県庁所在市及び政令指定都市ランキング」 / データ年: 2023年（令和５年）～2025年（令和７年）平均 / 取得日: 2026-08-10 / URL: https://www.stat.go.jp/data/kakei/zuhyou/rank10.xlsx
