VALUES
    ((SELECT id FROM batch_sets WHERE set_code = 'pref-ranking-1'), '002-ramen-out', 'top5-map', 'ラーメンにお金を使う県',
     '{"hook":"東京でも福岡でもない。ラーメン王国は、東北にあった。","trivia":"1位の山形県は21,695円。全国平均8,752円の約2.5倍で、2位の新潟県にも5千円近い差をつける独走です。上位5県のうち4県が日本海側と東北。寒い土地ほどラーメンにお金が動いています。","source_display":"総務省 家計調査 2023〜2025年平均（県庁所在市・政令市の世帯数加重平均で県換算）","result_list":"1位 山形県 21,695円\\n2位 新潟県 16,863円\\n3位 宮城県 14,207円\\n4位 栃木県 13,592円\\n5位 富山県 13,507円","value_suffix":"円","subtitle":"全国平均は8,752円","bg_motif":"湯気の立つラーメン丼とれんげ、雪をかぶった屋根瓦をあしらった落ち着いた和のモチーフ"}', '{"entries":[{"rank":1,"pref_code":6,"value":21695},{"rank":2,"pref_code":15,"value":16863},{"rank":3,"pref_code":4,"value":14207},{"rank":4,"pref_code":9,"value":13592},{"rank":5,"pref_code":16,"value":13507}]}', '{"20s":{"intro":"ラーメンにお金を使う県！","r5_call":"まずは5位！","r5_name":"富山県！","r4_call":"つぎは4位！","r4_name":"栃木県！","r3_call":"3位はどこだ！","r3_name":"宮城県！","r2_call":"惜しくも2位！","r2_name":"新潟県！","r1_call":"さあ、栄えある1位は！","r1_name":"山形県ーっ！","outro":"当たったかー？保存も頼む！"},"30s":{"intro":"ラーメンにお金を使う県、トップ5！","r5_call":"第5位！","r5_name":"富山県！","r5_comment":"北陸も強いぞ！","r4_call":"第4位！","r4_name":"栃木県！","r4_comment":"佐野が効いてる！","r3_call":"第3位！","r3_name":"宮城県！","r3_comment":"東北勢が続く！","r2_call":"第2位！","r2_name":"新潟県！","r2_comment":"これでも2位か！","r1_call":"さあ第1位、ラーメン王国は！","r1_name":"山形県ーっ！","recap":"山形、新潟、宮城、栃木、富山！","outro":"保存もよろしくな！"}}', '出典: 総務省統計局「家計調査 品目別都道府県庁所在市及び政令指定都市ランキング」 / データ年: 2023年（令和５年）～2025年（令和７年）平均 / 取得日: 2026-08-10 / URL: https://www.stat.go.jp/data/kakei/zuhyou/rank13.xlsx
