VALUES
    ((SELECT id FROM batch_sets WHERE set_code = 'pref-ranking-1'), '009-onsen-sources', 'top5-map', '温泉の源泉が多い県',
     '{"hook":"全国27,899本の源泉。その5本に1本近くが、この県にある。","trivia":"1位の大分県は5,094本。全国27,899本のおよそ18%が大分に集中しています。2位の鹿児島県2,735本、3位の北海道2,249本と続き、九州勢が上位に2県。源泉総数は利用中と未利用を合わせた本数です。","source_display":"環境省 令和6年度 温泉利用状況（令和7年3月末現在）","result_list":"1位 大分県 5,094本\\n2位 鹿児島県 2,735本\\n3位 北海道 2,249本\\n4位 静岡県 2,185本\\n5位 熊本県 1,339本","value_suffix":"本","subtitle":"全国の源泉は27,899本","bg_motif":"湯けむりの立つ露天風呂と手ぬぐい、湯の花と石畳をあしらった落ち着いた和のモチーフ"}', '{"entries":[{"rank":1,"pref_code":44,"value":5094},{"rank":2,"pref_code":46,"value":2735},{"rank":3,"pref_code":1,"value":2249},{"rank":4,"pref_code":22,"value":2185},{"rank":5,"pref_code":43,"value":1339}]}', '{"20s":{"intro":"温泉の源泉が多い県！","r5_call":"まずは5位！","r5_name":"熊本県！","r4_call":"つぎは4位！","r4_name":"静岡県！","r3_call":"3位はどこだ！","r3_name":"北海道！","r2_call":"惜しくも2位！","r2_name":"鹿児島県！","r1_call":"さあ、栄えある1位は！","r1_name":"大分県ーっ！","outro":"どこに行きたいかー？保存も！"},"30s":{"intro":"温泉の源泉が多い県、トップ5！","r5_call":"第5位！","r5_name":"熊本県！","r5_comment":"阿蘇の恵みだ！","r4_call":"第4位！","r4_name":"静岡県！","r4_comment":"伊豆と熱海だ！","r3_call":"第3位！","r3_name":"北海道！","r3_comment":"広さがものを言う！","r2_call":"第2位！","r2_name":"鹿児島県！","r2_comment":"火山のちからだ！","r1_call":"さあ第1位、温泉王国は！","r1_name":"大分県ーっ！","recap":"大分、鹿児島、北海道、静岡、熊本！","outro":"保存もよろしくな！"}}', '出典: 環境省「令和6年度温泉利用状況」 / データ年: 令和6年度（令和7年3月末現在） / 取得日: 2026-08-10 / URL: https://www.env.go.jp/nature/onsen/pdf/6-7_p_1.pdf
都道府県値をそのまま使用（市区町村統計ではないため県換算なし）。源泉総数 = 利用源泉数 A + 未利用源泉数 B。PDF の都道府県行を機械抽出して 47 件を降順に並べ替え、TOP6 に同値がないことを検査済み。', 1);

